#!/usr/bin/env bun
/**
 * La puerta al recomendador: dónde se ejecuta una clase de tarea, con qué
 * modelo y con qué esfuerzo.
 *
 * El problema que cierra. `cost/policy.ts` cruza los dos ejes —los registros
 * del catálogo contra los niveles de esfuerzo— y publica sus exclusiones con
 * razón. Estaba probado y era **inalcanzable desde donde se despacha**: se
 * despachó un agente en `claude-opus-5` donde `claude-fable-5-1` dominaba en
 * los dos ejes porque el operador no tenía cómo preguntar.
 *
 * Primero se mira la instalación: un modelo local con una medición aprobada
 * vigente de la clase y contexto suficiente gana, y se sirve por Ollama. Si
 * ninguno cumple, se cae al catálogo del proveedor por `claude-cli` y la
 * salida nombra la causa. `--runtime claude-cli` declara el proveedor de
 * forma explícita y la declaración queda en la salida.
 *
 * Por qué el contexto es un parámetro y no una constante: el orden cambia con
 * él, y además decide si la medición de un modelo local alcanza.
 *
 * Salidas: 0 con recomendación · 2 si ningún modelo cumple el perfil, si un
 * argumento no se entiende o si el catálogo local o sus cualificaciones son
 * ilegibles — nunca una recomendación por defecto, que sería elegir sin medir.
 */
import { readFile } from 'node:fs/promises'

def repository_root() -> pathlib.Path:
    """La raíz del árbol que contiene este archivo: el ``bin/`` que se genera es el suyo.

    Se localiza por ascenso hasta el marcador de thyrox, no por aritmética de
    ruta: ``parents[2]`` fallaba en silencio al mover el archivo.

    No se consulta ``THYROX_ROOT`` antes del ascenso, a diferencia de
    ``reach.thyrox_root()``: en una copia o un worktree la variable heredada
    nombra el clon original, y el generador escribía en SU ``bin/``
    (TASK-THYROX-0245). Sin marcador en ningún ancestro, se delega en el
    localizador general.
    """
    here = pathlib.Path(__file__).resolve().parent
    for level in (here, *here.parents):
        if (level / reach.THYROX_MARKER).is_file():
            return level
    return reach.thyrox_root()


def is_shell_entrypoint(path: pathlib.Path) -> bool:
    """Un ``.sh`` **con bit ejecutable**. El bit separa entrypoint de biblioteca.

    La versión anterior devolvía ``True`` para todo ``.sh``, con la razón
    escrita al lado: *"medido: ninguno es de biblioteca"*. Era cierto sobre las
    cinco carpetas que ``SOURCE_DIRS`` cubría entonces, y falso en cuanto el
    universo se ensanchó: los seis ``.sh`` de ``src/lib`` definen funciones para
    que otro guion las sourcee, y ninguno invoca nada.

    El criterio se midió contra las dos poblaciones conocidas antes de
    elegirlo, no se supuso:

    ======================================  ============  ==============
    Discriminador                           entrypoints   bibliotecas
    ======================================  ============  ==============
    bit ejecutable                          36 de 36      0 de 6
    hay una llamada de nivel superior       36 de 36      5 de 6  (falla)
    ======================================  ============  ==============

    El bit acierta en las dos direcciones; la heurística de llamada marca como
    entrypoint a cinco de las seis bibliotecas. Y el bit no es una convención
    que este archivo invente: es cómo POSIX separa "se ejecuta" de "se sourcea".
    """
    return path.suffix == ".sh" and os.access(path, os.X_OK)


def is_python_entrypoint(path: pathlib.Path) -> bool:
    """Tiene guarda de ``__main__`` — la biblioteca no la lleva, medido."""
    if path.suffix != ".py" or path.name == "__init__.py":
        return False
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(MAIN_GUARD.search(text))


def discover_entrypoints(root: pathlib.Path) -> dict[str, pathlib.Path]:
    """El mapa nombre-corto -> ruta absoluta, para las tres carpetas."""
    found: dict[str, pathlib.Path] = {}
    for rel_dir in SOURCE_DIRS:
        directory = root / rel_dir
        if not directory.is_dir():
            continue
        for entry in sorted(directory.iterdir()):
            if not entry.is_file():
                continue
            if is_shell_entrypoint(entry) or is_python_entrypoint(entry):
                stem = entry.stem
                if stem in found:
                    raise ValueError(
                        f"colisión de nombre corto: {stem!r} lo declaran "
                        f"{found[stem]} y {entry} — este generador rehúsa "
                        f"resolverla en silencio")
                found[stem] = entry
    return found


